import{_ as e,o as a,c as s,a5 as n}from"./chunks/framework.CXroN2RO.js";const r="/study/images/game/game-events-and-notifications.svg",u=JSON.parse('{"title":"ゲーム内イベントと通知 — HPの変化をUIへ伝える","description":"","frontmatter":{"title":"ゲーム内イベントと通知 — HPの変化をUIへ伝える","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"HPが変わる場面から、イベント、発行、購読、ハンドラー、通知する値、同期呼び出しとキュー、購読解除の役割を説明する。","aliases":["ゲームイベント","イベント","通知","event","publisher","subscriber","発行","購読","コールバック","ハンドラー","HPバー","Observer","イベントキュー"],"verification":"MicrosoftのC#イベント・.NETイベント処理・購読解除とUnity 6.0のUnityEvent公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/game-events-and-notifications.md","filePath":"game/basics/game-events-and-notifications.md"}'),o={name:"game/basics/game-events-and-notifications.md"};function i(d,t,c,l,p,h){return a(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="ゲーム内イベントと通知-—-hpの変化をuiへ伝える" tabindex="-1">ゲーム内イベントと通知 — HPの変化をUIへ伝える <a class="header-anchor" href="#ゲーム内イベントと通知-—-hpの変化をuiへ伝える" aria-label="Permalink to &quot;ゲーム内イベントと通知 — HPの変化をUIへ伝える&quot;">​</a></h1><p>敵に触れてHPが減ると、HPバーを短くし、ダメージの数字を表示することがあります。「HPが変わった」という出来事を、必要な処理へ伝える仕組みが<strong>イベント通知</strong>です。ここでは、ゲームのデータからUIへ変化を伝える場面を見ます。<a href="/study/game/basics/ui-layout-and-interaction.html">UIの表示と操作</a></p><h2 id="起きたことを、登録した処理へ伝える" tabindex="-1">起きたことを、登録した処理へ伝える <a class="header-anchor" href="#起きたことを、登録した処理へ伝える" aria-label="Permalink to &quot;起きたことを、登録した処理へ伝える&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>役割</th><th>HPの例</th></tr></thead><tbody><tr><td><strong>発行元</strong></td><td>出来事が起きたとき、通知を出す側。</td><td>HPを管理する処理。</td></tr><tr><td><strong>購読先</strong></td><td>通知を受けたいと登録する側。</td><td>HPバーを更新するUI。</td></tr><tr><td><strong>イベントハンドラー</strong></td><td>通知に応じて呼ばれる処理。</td><td>新しいHPに合わせてバーの長さを変える。</td></tr><tr><td><strong>イベントのデータ</strong></td><td>通知と一緒に伝える値。</td><td>新しいHP、最大HP、対象の識別子など。</td></tr></tbody></table><p>購読とは、通知に応じて呼ぶ処理を登録することです。C#の<code>event</code>では、発行元がイベントを発生させ、購読したハンドラーが処理を行います。一つのイベントに複数の処理を登録できます。<a href="https://learn.microsoft.com/en-us/dotnet/csharp/programming-guide/events/" target="_blank" rel="noreferrer">MicrosoftのC#イベント</a></p><figure class="study-figure"><img src="'+r+`" alt="HPを100から70へ更新した後、対象と新しいHPを通知する。通知を受けたHPバーが70を表示し、演出の処理が表示を始める。UIを用意するときに購読し、利用を終えるときに解除する。" width="760" height="446" loading="lazy"><figcaption>更新と通知の順序を決めた説明用の例です。通知を受けた各処理が、必要な表示を更新します。<a href="/study/images/game/game-events-and-notifications.svg" target="_blank" rel="noopener noreferrer">HPの更新と通知の図を拡大</a></figcaption></figure><h2 id="状態を更新してから、変化を知らせる" tabindex="-1">状態を更新してから、変化を知らせる <a class="header-anchor" href="#状態を更新してから、変化を知らせる" aria-label="Permalink to &quot;状態を更新してから、変化を知らせる&quot;">​</a></h2><p>この例では、次の順序で処理を行います。通知に渡す値と、受け手が読み直す値が合うように、どの段階で通知するかを決めます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ダメージを受ける</span></span>
<span class="line"><span>→ HPを100から70へ更新する</span></span>
<span class="line"><span>→ 新しいHPが70であることを通知する</span></span>
<span class="line"><span>→ UIが通知を受け、70の表示へ更新する</span></span></code></pre></div><p><strong>通知</strong>は起きたことの情報で、<strong>状態</strong>は現在保持している値です。途中から開くUIには、購読した時点で現在のHPを渡すなど、最初の表示を用意します。その後の変化を通知で反映すれば、画面を開く前に起きた更新も、今の値から表示できます。<a href="https://learn.microsoft.com/en-us/dotnet/standard/events/" target="_blank" rel="noreferrer">.NETのイベントと状態変更</a> · <a href="/study/design/case-studies/ui-notification.html">UI通知の設計</a></p><h2 id="いつ呼ばれるかを確認する" tabindex="-1">いつ呼ばれるかを確認する <a class="header-anchor" href="#いつ呼ばれるかを確認する" aria-label="Permalink to &quot;いつ呼ばれるかを確認する&quot;">​</a></h2><p>C#の通常のイベント呼び出しでは、登録したハンドラーを<strong>同期的に</strong>呼びます。発行元の処理はハンドラーの終了を待つので、重いハンドラーがあると待ち時間が長くなります。<a href="https://learn.microsoft.com/en-us/dotnet/csharp/programming-guide/events/" target="_blank" rel="noreferrer">Microsoftのイベントの呼び出し</a></p><p><strong>イベントキュー</strong>では、通知を一度ためて、ゲームループの決めた段階などで取り出します。後で処理するときには、対象がまだ存在するか、通知に入れた値はどの時点のものかを考えます。即座に呼ぶか、後へ渡すかは、採用する仕組みの規則で決まります。<a href="/study/game/patterns/event-queue-and-pubsub.html">Event Queue・Message Busの詳解</a></p><p>Unityには、エディターから呼び出す処理を設定する用途にも使える<strong>UnityEvent</strong>があります。C#の<code>event</code>や、独自のイベントキューと、登録方法や実行の規則をそれぞれ確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Events.UnityEvent.html" target="_blank" rel="noreferrer">UnityのUnityEvent</a> · <a href="/study/languages/csharp/delegates-events-function-pointers.html">delegateとevent</a></p><h2 id="購読の開始と終了をそろえる" tabindex="-1">購読の開始と終了をそろえる <a class="header-anchor" href="#購読の開始と終了をそろえる" aria-label="Permalink to &quot;購読の開始と終了をそろえる&quot;">​</a></h2><p>UIを表示し直すたびに同じ通知へ追加登録すると、一回の変化で同じ処理が複数回呼ばれることがあります。いつ登録し、いつ解除するかを、そのUIやオブジェクトの利用期間に合わせます。C#のイベントでは、発行元から購読先への参照が残ることも考慮します。<a href="https://learn.microsoft.com/en-us/dotnet/csharp/programming-guide/events/how-to-subscribe-to-and-unsubscribe-from-events" target="_blank" rel="noreferrer">Microsoftの購読と解除</a></p><p>例えば、有効な間だけ通知を受けるUIなら、有効化時に購読し、無効化時に解除する方針を取れます。表示を隠す処理とオブジェクトの破棄は別の操作なので、そのUIで何を終了とするかまで決めます。<a href="/study/game/basics/prefabs-and-object-lifetimes.html">プレハブとオブジェクトの寿命</a></p><p>ゲーム内の通知を使い分ける設計は<a href="/study/design/case-studies/ui-notification.html">UI通知の設計</a>、状態によって受け付ける処理を変える方法は<a href="/study/game/basics/game-states-and-pause.html">ゲームの状態とポーズ</a>へ進みます。</p>`,18)])])}const m=e(o,[["render",i]]);export{u as __pageData,m as default};
